JDP_st.name='JDP'; 
JDP_st.lat=26.28;
JDP_st.lon=73.02;
JDP_st.alt=0000;
JDP_st.env='Con';
JDP_st.footp='U';
%%
% data imported via the import tool from matlab

JDP_rd_h.Properties.DimensionNames{1}='Time';
JDP_rd_h.Properties.VariableNames{2}='Ba1_A';
JDP_rd_h.Properties.VariableNames{3}='Ba2_A';
JDP_rd_h.Properties.VariableNames{4}='Ba3_A';
JDP_rd_h.Properties.VariableNames{5}='Ba4_A';
JDP_rd_h.Properties.VariableNames{6}='Ba5_A';
JDP_rd_h.Properties.VariableNames{7}='Ba6_A';
JDP_rd_h.Properties.VariableNames{8}='Ba7_A';
names_rd=fieldnames(JDP_rd_h);
%%
JDP_rd=retime(JDP_rd_h,'daily',@nanmedian);
%%
datevec(JDP_rd.Time(1)) % begin in 2016,  %[output:3f05a8e4]
datevec(JDP_rd.Time(end)) % end in August 2021  %[output:810531c8]
plotFigControl(JDP_rd,JDP_st.name);  %[output:1d223a61] %[output:70cae0ae] %[output:9a15888c] %[output:0ecaa4c6] %[output:22fd6efc] %[output:8372c481]
%%
lambdaAE7=[370 470 520 590 660 880 950];
%compute abs exp
Ca3=startsWith(names_rd,{'Ba'}) & contains(names_rd,{'_A'});
names_abs=names_rd(Ca3);
JDP_cal=compute_exp_D(JDP_rd,names_abs,lambdaAE7); %[output:1f1930a6] %[output:7f0feede] %[output:86c6ae42] %[output:395a0ac7]
plotFigControl_cal(JDP_cal,JDP_st.name); %[output:630b4ef3] %[output:26afb344] %[output:8d22fc18]
%%
%HOMOGENEITY

break_JDP_abs_BP=change_point_analysis_Def(JDP_rd,names_abs,0.05,'JDP','Absorption'); %[output:619ba189] %[output:7f61b9b8] %[output:4c3af379] %[output:7b487b21] %[output:4c950dc3] %[output:305c063a]
T_JDP_abs_BP=make_table_breakpoints_def(break_JDP_abs_BP);

names_expA={'expA_bgAE','expA_brAE','expA_grAE','expA_fit'} %[output:4f05b9bf]
break_JDP_expA_BP=change_point_analysis_Def(JDP_cal,names_expA,0.05,'JDP','Absorption exponent'); %[output:65bc7f88] %[output:8efb6811] %[output:9425da58] %[output:02805667]
T_JDP_expA_BP=make_table_breakpoints_def(break_JDP_expA_BP); %[output:260a1886] %[output:21590761]


